INSERT INTO `component` VALUES (1,'Service Type','Select the type of service for the appointment.','./book-appointment-q1',0),(2,'Location','Choose the country and physical location for the appointment.','./book-appointment-q2',1),(3,'Group Booking','Add family or group members to the appointment.','./book-appointment-q3',1),(4,'Extra Time','Request additional time for the appointment based on special needs.','./book-appointment-q4',1),(5,'Language','Select preferred language and request an interpreter if needed.','./book-appointment-q5',1),(6,'AVS','Choose additional paid services (e.g., document scanning, printing).','./book-appointment-q6',1),(7,'Additional Notes','Provide any special requests or notes for staff.','./book-appointment-q7',1),(8,'Appointment Summary','Review all appointment details before confirmation.','./book-appointment-summary',0);
