--
-- Table structure for table `component_template`
--

DROP TABLE IF EXISTS `component_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `component_template` (
  `id` int NOT NULL AUTO_INCREMENT,
  `template_key` varchar(100) NOT NULL,
  `version` int NOT NULL DEFAULT '1',
  `type` varchar(50) NOT NULL,
  `label` varchar(100) NOT NULL,
  `description` text,
  `default_props` json NOT NULL,
  `prop_schema` json DEFAULT NULL,
  `export_njk_template` text,
  `status` varchar(20) DEFAULT 'active',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `has_options` tinyint(1) NOT NULL DEFAULT '0',
  `option_schema` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_component_template_key_version` (`template_key`,`version`),
  KEY `ix_component_template_key` (`template_key`),
  KEY `ix_component_template_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `component_template`
--

LOCK TABLES `component_template` WRITE;
/*!40000 ALTER TABLE `component_template` DISABLE KEYS */;
INSERT INTO `component_template` VALUES (1,'radio',1,'radio','Radio Group','A group of radio buttons letting users select one option.','{\"hint\": {\"text\": \"You can only choose one\"}, \"name\": \"example-radio\", \"items\": [{\"text\": \"Option 1\", \"value\": \"1\"}, {\"text\": \"Option 2\", \"value\": \"2\"}, {\"text\": \"Option 3\", \"value\": \"3\"}], \"classes\": \"govuk-radios\", \"disabled\": false, \"fieldset\": {\"legend\": {\"text\": \"Choose an option\", \"classes\": \"govuk-fieldset__legend--l\", \"isPageHeading\": false}}, \"formGroup\": {\"classes\": \"\"}}','[{\"key\": \"legendText\", \"path\": \"fieldset.legend.text\", \"type\": \"text\", \"label\": \"Legend Text\"}, {\"key\": \"hintText\", \"path\": \"hint.text\", \"type\": \"text\", \"label\": \"Hint Text\"}, {\"key\": \"legendClasses\", \"path\": \"fieldset.legend.classes\", \"type\": \"select\", \"label\": \"Legend Classes\", \"options\": [{\"label\": \"Default (none)\", \"value\": \"\"}, {\"label\": \"Small (s)\", \"value\": \"govuk-fieldset__legend--s\"}, {\"label\": \"Medium (m)\", \"value\": \"govuk-fieldset__legend--m\"}, {\"label\": \"Large (l)\", \"value\": \"govuk-fieldset__legend--l\"}, {\"label\": \"Extra Large (xl)\", \"value\": \"govuk-fieldset__legend--xl\"}]}, {\"key\": \"isPageHeading\", \"path\": \"fieldset.legend.isPageHeading\", \"type\": \"select\", \"label\": \"Is Page Heading?\", \"options\": [{\"label\": \"True\", \"value\": true}, {\"label\": \"False\", \"value\": false}]}, {\"key\": \"name\", \"path\": \"name\", \"type\": \"text\", \"label\": \"Data Key\"}, {\"key\": \"classes\", \"path\": \"classes\", \"type\": \"select\", \"label\": \"Container Classes\", \"options\": [{\"label\": \"Default\", \"value\": \"govuk-radios\"}, {\"label\": \"Inline\", \"value\": \"govuk-radios--inline\"}, {\"label\": \"Small\", \"value\": \"govuk-radios--small\"}, {\"label\": \"Inline + Small\", \"value\": \"govuk-radios--inline govuk-radios--small\"}]}, {\"key\": \"formGroupClasses\", \"path\": \"formGroup.classes\", \"type\": \"select\", \"label\": \"Form Group Classes\", \"options\": [{\"label\": \"Default (none)\", \"value\": \"\"}, {\"label\": \"Error State\", \"value\": \"govuk-form-group--error\"}]}, {\"key\": \"disabled\", \"path\": \"disabled\", \"type\": \"select\", \"label\": \"Disabled?\", \"options\": [{\"label\": \"True\", \"value\": true}, {\"label\": \"False\", \"value\": false}]}, {\"key\": \"options\", \"path\": \"items\", \"type\": \"optionList\", \"label\": \"Options\"}]','{% from \"govuk/components/radios/macro.njk\" import govukRadios %}\n{% set cls = props.classes or \'govuk-radios\' %}\n{% if \'govuk-radios\' not in cls %}{% set cls = \'govuk-radios \' + cls %}{% endif %}\n{{ govukRadios({\n  name: props.name,\n  fieldset: {\n    legend: {\n      text: props.fieldset.legend.text,\n      isPageHeading: props.fieldset.legend.isPageHeading,\n      classes: props.fieldset.legend.classes\n    }\n  },\n  hint: props.hint,\n  classes: cls,\n  formGroup: { classes: props.formGroup.classes },\n  disabled: props.disabled,\n  items: props.items\n}) }}','active','2025-03-25 10:10:39','2025-08-25 10:06:41',1,'[\"text\", \"value\", \"hint\"]'),(2,'select',1,'select','Select','Dropdown select allowing users to choose a single option from a list.','{\"id\": \"\", \"hint\": {\"text\": \"Select the applicable option.\"}, \"name\": \"example-select\", \"items\": [{\"text\": \"-- Select --\", \"value\": \"\"}, {\"text\": \"Option 1\", \"value\": \"opt1\"}, {\"text\": \"Option 2\", \"value\": \"opt2\"}], \"label\": {\"text\": \"Choose an option\", \"classes\": \"govuk-label--m\"}, \"classes\": \"govuk-select\", \"disabled\": false, \"formGroup\": {\"classes\": \"\"}, \"errorMessage\": {\"text\": \"\"}}','[{\"key\": \"name\", \"path\": \"name\", \"type\": \"text\", \"label\": \"Data Key\"}, {\"key\": \"label.text\", \"path\": \"label.text\", \"type\": \"text\", \"label\": \"Label Text\"}, {\"key\": \"label.classes\", \"path\": \"label.classes\", \"type\": \"select\", \"label\": \"Label Classes\", \"options\": [{\"label\": \"Default (m)\", \"value\": \"govuk-label--m\"}, {\"label\": \"Small (s)\", \"value\": \"govuk-label--s\"}, {\"label\": \"Large (l)\", \"value\": \"govuk-label--l\"}, {\"label\": \"Extra Large (xl)\", \"value\": \"govuk-label--xl\"}, {\"label\": \"Visually Hidden\", \"value\": \"govuk-visually-hidden\"}, {\"label\": \"None (inherit)\", \"value\": \"\"}]}, {\"key\": \"hint.text\", \"path\": \"hint.text\", \"type\": \"text\", \"label\": \"Hint Text\"}, {\"key\": \"classes\", \"path\": \"classes\", \"type\": \"select\", \"label\": \"CSS Classes\", \"options\": [{\"label\": \"Default (govuk-select)\", \"value\": \"govuk-select\"}, {\"label\": \"Full width (govuk-!-width-full)\", \"value\": \"govuk-select govuk-!-width-full\"}, {\"label\": \"One half (govuk-!-width-one-half)\", \"value\": \"govuk-select govuk-!-width-one-half\"}, {\"label\": \"One third (govuk-!-width-one-third)\", \"value\": \"govuk-select govuk-!-width-one-third\"}]}, {\"key\": \"formGroup.classes\", \"path\": \"formGroup.classes\", \"type\": \"select\", \"label\": \"Form Group Classes\", \"options\": [{\"label\": \"Default (none)\", \"value\": \"\"}, {\"label\": \"Error State\", \"value\": \"govuk-form-group--error\"}]}, {\"key\": \"disabled\", \"path\": \"disabled\", \"type\": \"select\", \"label\": \"Disabled?\", \"options\": [{\"label\": \"False\", \"value\": false}, {\"label\": \"True\", \"value\": true}]}, {\"key\": \"options\", \"path\": \"items\", \"type\": \"optionList\", \"label\": \"Options\"}]','{% from \"govuk/components/select/macro.njk\" import govukSelect %}\n{% set idVal = props.id or props.name %}\n{% set items = (props.items or []) %}\n{{ govukSelect({\n  id: idVal,\n  name: props.name,\n  label: props.label,\n  hint: props.hint,\n  errorMessage: props.errorMessage,\n  items: items,\n  classes: props.classes,\n  formGroup: props.formGroup,\n  disabled: props.disabled\n}) }}','active','2025-03-25 10:12:31','2025-09-05 09:21:25',1,'[\"text\", \"value\"]'),(5,'password-input',1,'password-input','Password Input','A password input that can be toggled to show or hide text.','{\"hint\": {\"text\": \"This is the optional hint text\"}, \"name\": \"password\", \"label\": {\"text\": \"Label\", \"classes\": \"govuk-label--m\"}, \"errorMessage\": {\"text\": \"\"}}','[{\"key\": \"name\", \"path\": \"name\", \"type\": \"text\", \"label\": \"Submission Key\"}, {\"key\": \"id\", \"path\": \"id\", \"type\": \"text\", \"label\": \"ID\"}, {\"key\": \"labelText\", \"path\": \"label.text\", \"type\": \"text\", \"label\": \"Label Text\"}, {\"key\": \"label.classes\", \"path\": \"label.classes\", \"type\": \"select\", \"label\": \"Label classes\", \"options\": [\"govuk-label\", \"govuk-label--s\", \"govuk-label--m\", \"govuk-label--l\", \"govuk-label--xl\"]}, {\"key\": \"hintText\", \"path\": \"hint.text\", \"type\": \"text\", \"label\": \"Hint Text\"}, {\"key\": \"classes\", \"path\": \"classes\", \"type\": \"text\", \"label\": \"CSS Classes\"}]','\n{% from \"govuk/components/password-input/macro.njk\" import govukPasswordInput %}\n\n{{ govukPasswordInput({\n  id: props.id,\n  name: props.name,\n  autocomplete: props.autocomplete,\n  disabled: props.disabled,\n  label: {\n    text: props.label.text,\n    classes: props.label.classes,\n    isPageHeading: props.label.isPageHeading\n  },\n  hint: {\n    text: props.hint.text\n  },\n  classes: props.classes,\n  formGroup: {\n    classes: props.formGroup.classes\n  },\n  showPasswordText: props.showPasswordText,\n  hidePasswordText: props.hidePasswordText,\n  showPasswordAriaLabelText: props.showPasswordAriaLabelText,\n  hidePasswordAriaLabelText: props.hidePasswordAriaLabelText\n}) }}\n','active','2025-03-25 17:58:47','2025-08-22 16:41:41',0,NULL),(12,'accordion',1,'accordion','Accordion','A collapsible section component where multiple sections can be expanded or collapsed.','{\"id\": \"default-example\", \"items\": [{\"content\": {\"text\": \"We need to know your nationality so we can work out which elections you’re entitled to vote in. If you cannot provide your nationality, you’ll have to send copies of identity documents through the post.\"}, \"heading\": {\"text\": \"Section A\"}}, {\"content\": {\"html\": \"<ul class=\\\"govuk-list govuk-list--bullet\\\"><li>Example item 2</li></ul>\"}, \"heading\": {\"text\": \"Section B\"}}], \"classes\": \"\", \"headingLevel\": 2, \"rememberExpanded\": false, \"hideAllSectionsText\": \"Hide all sections\", \"showAllSectionsText\": \"Show all sections\"}','[{\"key\": \"id\", \"path\": \"id\", \"type\": \"text\", \"label\": \"ID\"}, {\"key\": \"items\", \"path\": \"items\", \"type\": \"text\", \"label\": \"Items (JSON string)\"}, {\"key\": \"classes\", \"path\": \"classes\", \"type\": \"text\", \"label\": \"CSS Classes\"}]','\n{% from \"govuk/components/accordion/macro.njk\" import govukAccordion %}\n\n{{ govukAccordion({\n  id: props.id,\n  headingLevel: props.headingLevel,\n  rememberExpanded: props.rememberExpanded,\n  showAllSectionsText: props.showAllSectionsText,\n  hideAllSectionsText: props.hideAllSectionsText,\n  classes: props.classes,\n  items: props.items\n}) }}\n','inactive','2025-03-26 14:31:28','2025-08-18 15:53:52',0,'[\"heading.text\", \"content.text\"]'),(13,'date-input',1,'date-input','Date Input','Collect a date using separate day, month and year inputs.','{\"hint\": {\"text\": {\"en\": \"For example, 27 3 2007\", \"fr\": \"Par exemple, 27 3 2007\"}}, \"name\": \"example-date\", \"items\": [{\"name\": \"day\", \"classes\": \"govuk-input--width-2\"}, {\"name\": \"month\", \"classes\": \"govuk-input--width-2\"}, {\"name\": \"year\", \"classes\": \"govuk-input--width-4\"}], \"classes\": \"\", \"disabled\": false, \"fieldset\": {\"legend\": {\"text\": {\"en\": \"Enter the date\", \"fr\": \"Entrez la date\"}, \"classes\": \"govuk-fieldset__legend--l\", \"isPageHeading\": false}}, \"formGroup\": {\"classes\": \"\"}, \"autocompletePreset\": \"\"}','[{\"key\": \"legendText\", \"path\": \"fieldset.legend.text\", \"type\": \"text\", \"label\": \"Legend Text\"}, {\"key\": \"hintText\", \"path\": \"hint.text\", \"type\": \"text\", \"label\": \"Hint Text\"}, {\"key\": \"legendClasses\", \"path\": \"fieldset.legend.classes\", \"type\": \"select\", \"label\": \"Legend Classes\", \"options\": [{\"label\": \"Default (none)\", \"value\": \"\"}, {\"label\": \"Small (s)\", \"value\": \"govuk-fieldset__legend--s\"}, {\"label\": \"Medium (m)\", \"value\": \"govuk-fieldset__legend--m\"}, {\"label\": \"Large (l)\", \"value\": \"govuk-fieldset__legend--l\"}, {\"label\": \"Extra Large (xl)\", \"value\": \"govuk-fieldset__legend--xl\"}]}, {\"key\": \"isPageHeading\", \"path\": \"fieldset.legend.isPageHeading\", \"type\": \"select\", \"label\": \"Is Page Heading?\", \"options\": [{\"label\": \"True\", \"value\": true}, {\"label\": \"False\", \"value\": false}]}, {\"key\": \"name\", \"path\": \"name\", \"type\": \"text\", \"label\": \"Data Key\"}, {\"key\": \"autocompletePreset\", \"path\": \"autocompletePreset\", \"type\": \"select\", \"label\": \"Autocomplete Preset\", \"options\": [{\"label\": \"None\", \"value\": \"\"}, {\"label\": \"Date of Birth (bday-day / bday-month / bday-year)\", \"value\": \"dob\"}, {\"label\": \"Disable (off)\", \"value\": \"off\"}]}, {\"key\": \"formGroup.classes\", \"path\": \"formGroup.classes\", \"type\": \"select\", \"label\": \"Form Group Classes\", \"options\": [{\"label\": \"Default (none)\", \"value\": \"\"}, {\"label\": \"Error State\", \"value\": \"govuk-form-group--error\"}]}, {\"key\": \"disabled\", \"path\": \"disabled\", \"type\": \"select\", \"label\": \"Disabled?\", \"options\": [{\"label\": \"True\", \"value\": true}, {\"label\": \"False\", \"value\": false}]}]','{% from \"govuk/components/date-input/macro.njk\" import govukDateInput %}\n{{ govukDateInput({\n  id: props.name,\n  namePrefix: props.name,\n  fieldset: {\n    legend: { text: props.fieldset.legend.text, isPageHeading: props.fieldset.legend.isPageHeading, classes: props.fieldset.legend.classes }\n  },\n  hint: props.hint,\n  formGroup: { classes: props.formGroup.classes },\n  classes: props.classes,\n  items: props.items,\n  disabled: props.disabled\n}) }}','active','2025-03-26 14:33:20','2025-08-25 11:49:49',0,'null'),(17,'details',1,'details','Details','Expandable disclosure for secondary information.','{\"id\": \"\", \"html\": \"\", \"open\": false, \"text\": \"This is hidden by default.\", \"classes\": \"\", \"summaryText\": \"More details\"}','[{\"key\": \"summaryText\", \"path\": \"summaryText\", \"type\": \"text\", \"label\": \"Summary Text\"}, {\"key\": \"text\", \"path\": \"text\", \"type\": \"textarea\", \"label\": \"Details Text\"}, {\"key\": \"html\", \"path\": \"html\", \"type\": \"textarea\", \"label\": \"Details HTML\"}, {\"key\": \"open\", \"path\": \"open\", \"type\": \"select\", \"label\": \"Open by default?\", \"options\": [{\"label\": \"False\", \"value\": false}, {\"label\": \"True\", \"value\": true}]}, {\"key\": \"classes\", \"path\": \"classes\", \"type\": \"text\", \"label\": \"CSS Classes\"}]','{% from \"govuk/components/details/macro.njk\" import govukDetails %}\n{{ govukDetails({\n  summaryText: props.summaryText,\n  text: props.text,\n  html: props.html,\n  open: props.open,\n  id: props.id,\n  classes: props.classes\n}) }}','active','2025-03-27 16:59:34','2025-08-26 13:20:17',0,'null'),(19,'file-upload',1,'file-upload','File Upload','Upload one or more supporting documents (bilingual-ready label & hint).','{\"id\": \"\", \"hint\": {\"text\": {\"en\": \"This is the hint text for file upload\", \"fr\": \"Ceci est le texte d\'aide pour le téléversement\"}}, \"name\": \"uploaded-file\", \"label\": {\"text\": {\"en\": \"Upload a file\", \"fr\": \"Téléversez un fichier\"}, \"classes\": \"govuk-label--m\"}, \"accept\": \".pdf,.jpg,.jpeg,.png,.gif,.heic\", \"classes\": \"\", \"disabled\": false, \"multiple\": false, \"formGroup\": {\"classes\": \"\"}, \"maxSizeMb\": 10, \"showMaxSize\": false, \"documentType\": \"\", \"errorMessage\": {\"text\": \"\"}, \"showMimeList\": false, \"documentLabel\": \"\"}','[{\"key\": \"name\", \"path\": \"name\", \"type\": \"text\", \"label\": \"Data Key\"}, {\"key\": \"label.text\", \"path\": \"label.text\", \"type\": \"text\", \"label\": \"Label Text\"}, {\"key\": \"label.classes\", \"path\": \"label.classes\", \"type\": \"select\", \"label\": \"Label Classes\", \"options\": [{\"label\": \"Medium (m)\", \"value\": \"govuk-label--m\"}, {\"label\": \"Small (s)\", \"value\": \"govuk-label--s\"}, {\"label\": \"Large (l)\", \"value\": \"govuk-label--l\"}, {\"label\": \"Extra Large (xl)\", \"value\": \"govuk-label--xl\"}, {\"label\": \"Visually Hidden\", \"value\": \"govuk-visually-hidden\"}, {\"label\": \"None\", \"value\": \"\"}]}, {\"key\": \"hint.text\", \"path\": \"hint.text\", \"type\": \"text\", \"label\": \"Hint Text\"}, {\"key\": \"multiple\", \"path\": \"multiple\", \"type\": \"select\", \"label\": \"Allow Multiple?\", \"options\": [{\"label\": \"No\", \"value\": false}, {\"label\": \"Yes\", \"value\": true}]}, {\"key\": \"maxSizeMb\", \"path\": \"maxSizeMb\", \"type\": \"number\", \"label\": \"Max Size (MB)\"}, {\"key\": \"accept\", \"path\": \"accept\", \"type\": \"text\", \"label\": \"Accept (MIME list)\"}, {\"key\": \"showMimeList\", \"path\": \"showMimeList\", \"type\": \"select\", \"label\": \"Show MIME List?\", \"options\": [{\"label\": \"Yes\", \"value\": true}, {\"label\": \"No\", \"value\": false}]}, {\"key\": \"showMaxSize\", \"path\": \"showMaxSize\", \"type\": \"select\", \"label\": \"Show Max Size?\", \"options\": [{\"label\": \"Yes\", \"value\": true}, {\"label\": \"No\", \"value\": false}]}, {\"key\": \"documentLabel\", \"path\": \"documentLabel\", \"type\": \"text\", \"label\": \"Document Label (display name)\"}, {\"key\": \"documentType\", \"path\": \"documentType\", \"type\": \"text\", \"label\": \"Document Type (metadata)\"}, {\"key\": \"classes\", \"path\": \"classes\", \"type\": \"text\", \"label\": \"CSS Classes\"}, {\"key\": \"formGroup.classes\", \"path\": \"formGroup.classes\", \"type\": \"select\", \"label\": \"Form Group Classes\", \"options\": [{\"label\": \"Default (none)\", \"value\": \"\"}, {\"label\": \"Error State\", \"value\": \"govuk-form-group--error\"}]}, {\"key\": \"disabled\", \"path\": \"disabled\", \"type\": \"select\", \"label\": \"Disabled?\", \"options\": [{\"label\": \"False\", \"value\": false}, {\"label\": \"True\", \"value\": true}]}]','{% set theId = props.id or props.name %}\n{% set labelObj = props.label %}\n{% set hintObj = props.hint %}\n{% set sizeMb = props.maxSizeMb or 10 %}\n{% set types = props.accept or \'.pdf,.jpg,.jpeg,.png,.gif,.heic\' %}\n<div class=\"govuk-form-group {{ props.formGroup.classes }}\">\n  {% if labelObj %}\n  <label class=\"govuk-label {{ labelObj.classes }}\" for=\"{{ theId }}\">{{ labelObj.text }}</label>\n  {% endif %}\n  {% if hintObj and hintObj.text %}<div class=\"govuk-hint\">{{ hintObj.text }}</div>{% endif %}\n  <input class=\"govuk-file-upload {{ props.classes }}\" id=\"{{ theId }}\" name=\"{{ props.name }}\" type=\"file\"{% if props.multiple %} multiple{% endif %}{% if props.accept %} accept=\"{{ props.accept }}\"{% endif %}{% if props.documentLabel %} data-document-label=\"{{ props.documentLabel }}\"{% endif %}{% if props.documentType %} data-document-type=\"{{ props.documentType }}\"{% endif %}{% if props.maxSizeMb is defined %} data-max-size-mb=\"{{ props.maxSizeMb }}\"{% endif %}{% if props.disabled %} disabled{% endif %}>\n  {% if props.showMimeList %}<div class=\"govuk-hint\">Allowed types: {{ types }}</div>{% endif %}\n  {% if props.showMaxSize %}<div class=\"govuk-hint\">Max size: {{ sizeMb }}MB.</div>{% endif %}\n</div>','active','2025-03-27 17:03:12','2025-11-25 10:07:28',0,'null'),(20,'warning-text',1,'warning-text','Warning Text','GOV.UK styled warning callout box with icon.','{\"id\": \"\", \"name\": \"warning-text\", \"role\": \"alert\", \"text\": {\"