INSERT INTO `iset_runtime_config` VALUES (1,'public','ai.model','{\"model\": \"openai/gpt-4.1-mini\"}','2026-01-11 13:50:31'),(2,'public','ai.fallbacks','[]','2025-12-01 12:08:36'),(4,'events_capture','case_lifecycle','{\"types\": {\"auto_assigned\": {\"enabled\": true}, \"case_assigned\": {\"enabled\": true}, \"status_changed\": {\"enabled\": true}, \"case_reassigned\": {\"enabled\": true}, \"case_unassigned\": {\"enabled\": true}, \"case_watch_added\": {\"enabled\": true}, \"case_watch_removed\": {\"enabled\": true}}, \"enabled\": true}','2025-11-24 16:03:15'),(6,'events_capture','case_lifecycle.case_assigned','{\"enabled\": true, \"updated_at\": \"2025-09-30T19:20:47.129Z\", \"updated_by\": \"7cad7598-d0d1-708d-0d42-d2abfe7dd933\"}','2025-09-30 15:20:47'),(7,'events_capture','case_lifecycle.case_unassigned','{\"enabled\": true, \"updated_at\": \"2025-09-30T19:20:48.009Z\", \"updated_by\": \"7cad7598-d0d1-708d-0d42-d2abfe7dd933\"}','2025-09-30 15:20:48'),(10,'events_capture','assessment.assessment_submitted','{\"enabled\": true, \"updated_at\": \"2025-09-30T19:19:18.562Z\", \"updated_by\": \"7cad7598-d0d1-708d-0d42-d2abfe7dd933\"}','2025-09-30 15:19:18'),(12,'events_capture','assessment.nwac_review_submitted','{\"enabled\": true, \"updated_at\": \"2025-09-30T19:19:20.622Z\", \"updated_by\": \"7cad7598-d0d1-708d-0d42-d2abfe7dd933\"}','2025-09-30 15:19:20'),(14,'events_capture','case_lifecycle.status_changed','{\"enabled\": true, \"updated_at\": \"2025-09-30T19:20:46.118Z\", \"updated_by\": \"7cad7598-d0d1-708d-0d42-d2abfe7dd933\"}','2025-09-30 15:20:46'),(17,'events_capture','case_lifecycle.case_reassigned','{\"enabled\": true, \"updated_at\": \"2025-09-30T19:20:49.147Z\", \"updated_by\": \"7cad7598-d0d1-708d-0d42-d2abfe7dd933\"}','2025-09-30 15:20:49'),(18,'events_capture','case_lifecycle.case_approved','{\"enabled\": true, \"updated_at\": \"2025-09-30T19:20:51.006Z\", \"updated_by\": \"7cad7598-d0d1-708d-0d42-d2abfe7dd933\"}','2025-09-30 15:20:51'),(19,'events_capture','case_lifecycle.case_rejected','{\"enabled\": true, \"updated_at\": \"2025-09-30T19:20:52.128Z\", \"updated_by\": \"7cad7598-d0d1-708d-0d42-d2abfe7dd933\"}','2025-09-30 15:20:52'),(26,'events_capture','application_lifecycle.application_saved_draft','{\"enabled\": true, \"updated_at\": \"2025-11-04T13:13:35.084Z\", \"updated_by\": \"7cad7598-d0d1-708d-0d42-d2abfe7dd933\"}','2025-11-04 08:13:35'),(27,'events_capture','application_lifecycle.application_draft_deleted','{\"enabled\": true, \"updated_at\": \"2025-11-04T13:13:36.957Z\", \"updated_by\": \"7cad7598-d0d1-708d-0d42-d2abfe7dd933\"}','2025-11-04 08:13:36'),(28,'events_capture','application_lifecycle.application_created','{\"enabled\": true, \"updated_at\": \"2025-11-04T13:13:33.299Z\", \"updated_by\": \"7cad7598-d0d1-708d-0d42-d2abfe7dd933\"}','2025-11-04 08:13:33'),(29,'admin','locking','{\"mode\": \"optimistic\", \"lockTtlMinutes\": 15, \"heartbeatMinutes\": 2}','2025-10-12 13:26:59'),(33,'admin','accessControlMatrix','{\"routes\": {\"/iset/cases\": [\"System Administrator\", \"Program Administrator\", \"Regional Coordinator\", \"Application Assessor\"], \"/cases/:caseId\": [\"System Administrator\", \"Program Administrator\", \"Regional Coordinator\", \"Application Assessor\"], \"/esdc/overview\": [\"System Administrator\"], \"/access-control\": [\"System Administrator\", \"Program Administrator\"], \"/arms-reporting\": [\"System Administrator\"], \"/esdc/reporting\": [\"System Administrator\"], \"/iset/cases/new\": [\"System Administrator\", \"Program Administrator\"], \"/finance/budgets\": [\"System Administrator\", \"Program Administrator\"], \"/finance/reports\": [\"System Administrator\", \"Program Administrator\"], \"/modify-workflow\": [\"System Administrator\", \"Program Administrator\"], \"/ptma-management\": [\"System Administrator\"], \"/template-editor\": [\"System Administrator\", \"Program Administrator\"], \"/visual-settings\": [\"System Administrator\"], \"/finance/overview\": [\"System Administrator\", \"Program Administrator\"], \"/finance/payments\": [\"System Administrator\", \"Program Administrator\"], \"/finance/settings\": [\"System Administrator\", \"Program Administrator\"], \"/manage-workflows\": [\"System Administrator\", \"Program Administrator\"], \"/esdc/participants\": [\"System Administrator\", \"Program Administrator\"], \"/manage-components\": [\"System Administrator\", \"Program Administrator\"], \"/finance/monitoring\": [\"System Administrator\", \"Program Administrator\"], \"/admin/upload-config\": [\"System Administrator\", \"Program Administrator\"], \"/finance/allocations\": [\"System Administrator\", \"Program Administrator\"], \"/finance/forecasting\": [\"System Administrator\", \"Program Administrator\"], \"/nwac-hub-management\": [\"System Administrator\"], \"/reporting-dashboard\": [\"System Administrator\"], \"/tutorials-dashboard\": [\"System Administrator\", \"Program Administrator\", \"Regional Coordinator\", \"Application Assessor\"], \"/application-case/:id\": [\"System Administrator\", \"Program Administrator\", \"Regional Coordinator\", \"Application Assessor\"], \"/audit-logs-dashboard\": [\"System Administrator\"], \"/configuration/events\": [\"System Administrator\", \"Program Administrator\"], \"/manage-notifications\": [\"System Administrator\", \"Program Administrator\"], \"/modify-component/:id\": [\"System Administrator\", \"Program Administrator\"], \"/configuration-settings\": [\"System Administrator\", \"Program Administrator\"], \"/contact-communications\": [\"System Administrator\", \"Program Administrator\"], \"/finance/reconciliation\": [\"System Administrator\", \"Program Administrator\"], \"/help-support-dashboard\": [\"System Administrator\", \"Program Administrator\", \"Regional Coordinator\", \"Application Assessor\"], \"/manage-security-options\": [\"System Administrator\", \"Program Administrator\"], \"/service-levels-dashboard\": [\"System Administrator\"], \"/case-assignment-dashboard\": [\"System Administrator\", \"Program Administrator\", \"Regional Coordinator\", \"Application Assessor\"], \"/user-management-dashboard\": [\"System Administrator\", \"Program Administrator\", \"Regional Coordinator\"], \"/capacity-planning-dashboard\": [\"System Administrator\"], \"/custom-dashboards-dashboard\": [\"System Administrator\"], \"/language-settings-dashboard\": [\"System Administrator\"], \"/release-management-dashboard\": [\"System Administrator\"], \"/system-performance-dashboard\": [\"System Administrator\"], \"/reporting-and-monitoring-dashboard\": [\"System Administrator\"], \"/case-assignment-dashboard?view=assignment\": [\"System Administrator\"]}, \"default\": \"deny\"}','2025-12-12 20:33:09'),(58,'publish','workflow.schema.intake','{\"meta\": {\"checksum\": \"fa0ea9d3d35936ae729b5e53a5dc0f655db07f1cf80ce1cf468e798a314ec42b\", \"schemaMeta\": {\"counts\": {\"steps\": 23, \"components\": 144}, \"workflow\": {\"id\": 21, \"name\": \"ISET Intake\", \"status\": \"active\"}, \"templates\": [{\"id\": 29, \"type\": \"paragraph\", \"count\": 50, \"version\": 1, \"template_key\": \"text-block\"}, {\"id\": 35, \"type\": \"signature-ack\", \"count\": 4, \"version\": 1, \"template_key\": \"signature-ack\"}, {\"id\": 26, \"type\": \"input\", \"count\": 48, \"version\": 1, \"template_key\": \"input\"}, {\"id\": 1, \"type\": \"radio\", \"count\": 16, \"version\": 1, \"template_key\": \"radio\"}, {\"id\": 32, \"type\": \"textarea\", \"count\": 3, \"version\": 1, \"template_key\": \"textarea\"}, {\"id\": 13, \"type\": \"date-input\", \"count\": 1, \"version\": 1, \"template_key\": \"date-input\"}, {\"id\": 2, \"type\": \"select\", \"count\": 2, \"version\": 1, \"template_key\": \"select\"}, {\"id\": 31, \"type\": \"character-count\", \"count\": 3, \"version\": 1, \"template_key\": \"character-count\"}, {\"id\": 33, \"type\": \"checkbox\", \"count\": 4, \"version\": 1, \"template_key\": \"checkbox\"}, {\"id\": 24, \"type\": \"summary-list\", \"count\": 9, \"version\": 1, \"template_key\": \"summary-list\"}, {\"id\": 19, \"type\": \"file-upload\", \"count\": 17, \"version\": 1, \"template_key\": \"file-upload\"}], \"generatedAt\": \"2026-01-21T18:08:38.696Z\", \"schemaVersion\": \"1.1\"}, \"workflowId\": 21, \"generatedAt\": \"2026-01-21T18:08:38.698Z\"}, \"schema\": [{\"type\": \"schema\", \"title\": {\"en\": \"Consent\", \"fr\": \"Consent\"}, \"stepId\": \"consent\", \"components\": [{\"id\": \"paragraph\", \"text\": {\"en\": \"Consent Form\", \"fr\": \"Formulaire de consentement\"}, \"type\": \"paragraph\", \"class\": \"govuk-heading-l\"}, {\"id\": \"paragraph-2\", \"text\": {\"en\": \"I, the undersigned, give my expressed and informed consent to the Native Women’s Association of Canada and/or its sub-agreement holders to the Indigenous Skills and Employment Training Program (hereinafter referred to as ISET), to collect personal or sensitive information as it relates to my request for funding under the ISET program funded by Employment and Social Development Canada (ESDC). My consent extends to providing my Social Insurance Number (SIN), to determine my eligibility for interventions such as skills training and wage subsidies as part of the Labour Market Development Agreements (LMDA) program.\", \"fr\": \"Je, le soussigné, donne mon consentement exprès et éclairé à l’Association des Femmes Autochtones du Canada et/ou à ses titulaires de sous-ententes liées au Programme des compétences et de la formation à l’emploi des Autochtones (ci-après dénommé PCFÉA), pour recueillir des renseignements personnels ou sensibles concernant ma demande de financement dans le cadre du programme PCFÉA financé par Emploi et Développement social Canada (EDSC). Mon consentement s’étend à la fourniture de mon numéro d’assurance sociale (NAS), afin de déterminer mon admissibilité à des interventions telles que la formation professionnelle et les subventions salariales dans le cadre des Ententes de développement du marché du travail (EDMT).\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-3\", \"text\": {\"en\": \"I acknowledge that the information is collected and administered in accordance with the Privacy Act (R.S.C. 1985, c P-21), the Department Employment and Social Development Canada Act (S.C. 2005, c.34), and and the Access to Information Act (R.S.C., 1985, c.A-1). Information collected is to be used to determine eligibility for the ISET program; to measure results of this Agreement and evaluate its success; evaluate the effectiveness of the Program in achieving its objective; and, to meet its obligations of accountability by reporting on the results of the Program.\", \"fr\": \"Je reconnais que les renseignements sont recueillis et administrés conformément à la Loi sur la protection des renseignements personnels (L.R.C. 1985, ch. P-21), à la Loi sur le ministère de l’Emploi et du Développement social Canada (L.C. 2005, ch. 34) et à la Loi sur l’accès à l’information (L.R.C., 1985, ch. A-1). Les renseignements recueillis sont utilisés pour déterminer l’admissibilité au programme PCFÉA; pour mesurer les résultats de la présente entente et en évaluer le succès; pour évaluer l’efficacité du Programme à atteindre ses objectifs; et, pour répondre aux obligations de reddition de comptes en rapportant les résultats du Programme.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-4\", \"text\": {\"en\": \"All information referred to above shall be treated as confidential, and the Native Women’s Association of Canada and its sub-agreement holders will take all security measures reasonably necessary for the protection of such information against unauthorized release or disclosure.\", \"fr\": \"Tous les renseignements mentionnés ci-dessus seront traités comme confidentiels, et l’Association des Femmes Autochtones du Canada ainsi que ses titulaires de sous-ententes prendront toutes les mesures de sécurité raisonnablement nécessaires pour protéger ces renseignements contre tout dévoilement ou divulgation non autorisée.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-5\", \"text\": {\"en\": \"Further, I understand that my personal information shall not be used or disclosed for purposes other than those for which it was collected, except with the expressed consent of you, as the client, or as required by law. Personal information shall be retained only as long as necessary for the fulfilment of those purposes.\", \"fr\": \"De plus, je comprends que mes renseignements personnels ne seront pas utilisés ni divulgués à des fins autres que celles pour lesquelles ils ont été recueillis, sauf avec mon consentement exprès en tant que client, ou si la loi l’exige. Les renseignements personnels seront conservés seulement aussi longtemps que nécessaire pour remplir ces objectifs.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"consent\", \"hint\": {\"en\": \"I confirm that I have read and understood the above consent and agree to proceed with my application.\", \"fr\": \"Je confirme avoir lu et compris le consentement ci-dessus et j\'accepte de poursuivre ma demande.\"}, \"type\": \"signature-ack\", \"label\": {\"en\": \"Sign Here\", \"fr\": \"Signer avant de procéder\"}, \"required\": true, \"normalize\": \"none\", \"boxPadding\": \"m\", \"clearLabel\": {\"en\": \"Clear\", \"fr\": \"Effacer\"}, \"labelClass\": \"govuk-label--m\", \"storageKey\": \"consent\", \"actionLabel\": {\"en\": \"Sign Now\", \"fr\": \"Signer Maintenant\"}, \"placeholder\": {\"en\": \"First Name Last Name\", \"fr\": \"Prénom Nom\"}, \"handwritingFont\": \"cursive\", \"statusSignedText\": {\"en\": \"Signed\", \"fr\": \"Signé\"}, \"statusUnsignedText\": {\"en\": \"Unsigned\", \"fr\": \"Non signé\"}}], \"nextStepId\": \"indigenous-declaration\", \"description\": {\"en\": \"\", \"fr\": \"\"}}, {\"type\": \"schema\", \"title\": {\"en\": \"Indigenous Declaration\", \"fr\": \"Indigenous Declaration\"}, \"stepId\": \"indigenous-declaration\", \"components\": [{\"id\": \"paragraph\", \"text\": {\"en\": \"Indigenous Declaration\", \"fr\": \"Déclaration autochtone\"}, \"type\": \"paragraph\", \"class\": \"govuk-heading-l\"}, {\"id\": \"paragraph-2\", \"text\": {\"en\": \"I, the undersigned, understand that the funding opportunity under the Indigenous Skills and Employment Training (ISET) program for which I am being assessed is intended to increase Indigenous participation in the Canadian labour market and support First Nations, Metis and Inuit peoples’ access to sustainable and meaningful employment. The ISET program provides access to training and employment supports to eligible Canadian Indigenous women in their diversities, including status and non-status First Nations, Metis and Inuit peoples whether residing on or off-reserve, in urban centres and in rural, remote communities.\", \"fr\": \"Je, le soussigné, comprends que l’opportunité de financement dans le cadre du programme de formation en compétences et emploi pour les Autochtones (FCEA) pour laquelle je suis évalué vise à augmenter la participation des Autochtones sur le marché du travail canadien et à soutenir l\'accès des Premières Nations, des Métis et des Inuits à un emploi durable et significatif. Le programme FCEA offre un accès à la formation et à un soutien à l’emploi aux femmes autochtones canadiennes admissibles dans leur diversité, y compris aux Premières Nations avec et sans statut, aux Métis et aux Inuits, qu’elles résident dans des réserves ou hors réserve, dans des centres urbains ou dans des collectivités rurales ou éloignées.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-3\", \"text\": {\"en\": \"Further, I understand that providing false or misleading information and/or omission of information by me about my Indigenous identity may result in an investigation. If an investigation is founded, it will be grounds for immediate suspension of any funding provided or promised to me and further, revocation of any Funding Agreement signed between me and the Native Women’s Association of Canada and/or its sub-agreement holders, and will result in a repayment of funds to Employment and Social Development Canada (ESDC), for monies I received to which I was not entitled.\", \"fr\": \"De plus, je comprends que fournir des informations fausses ou trompeuses et/ou omettre des informations concernant mon identité autochtone peut entraîner une enquête. Si une enquête donne lieu à des constatations, cela constituera un motif de suspension immédiate de tout financement qui m’a été accordé ou promis et, en outre, la révocation de toute entente de financement signée entre moi et l’Association des femmes autochtones du Canada et/ou ses titulaires de sous-entente, et entraînera le remboursement de fonds à Emploi et Développement social Canada (EDSC) pour des sommes reçues auxquelles je n’avais pas droit.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"indigenous-affiliation-declaration\", \"hint\": {\"en\": \"(e.g., Mohawks of Kahnawà:ke ; Inuit of Nunatsiavut; Metis Nation of  Alberta, Region 3, etc.)\", \"fr\": \"(p. ex., Mohawk de Kahnawa:ke; Inuit de Nunatsiavut; Nation métisse de l’Alberta, région 3, etc.)\"}, \"type\": \"input\", \"class\": \"govuk-input\", \"label\": {\"en\": \"My Nation/Community/Treaty Area affiliation\", \"fr\": \"Affiliation à ma nation/communauté/territoire de traité\"}, \"required\": true, \"inputType\": \"text\", \"normalize\": \"trim\", \"labelClass\": \"govuk-label--s\", \"spellcheck\": true, \"storageKey\": \"indigenous-affiliation-declaration\", \"validation\": {\"required\": true, \"requiredMessage\": {\"en\": \"Please enter your affiliation\", \"fr\": \"Veuillez indiquer votre affiliation\"}}}, {\"id\": \"indigenous-declaration\", \"hint\": {\"en\": \"I hereby declare that I am an Indigenous person in Canada, which for the purposes of the Indigenous Skills and Employment Training (ISET) Program is inclusive of persons who are First Nations, Inuit, or Metis.\", \"fr\": \"Je déclare par la présente que je suis une personne autochtone au Canada, ce qui, pour les fins du programme de formation en compétences et emploi pour les Autochtones (FCEA), inclut les personnes qui sont Premières Nations, Inuits ou Métis.\"}, \"type\": \"signature-ack\", \"label\": {\"en\": \"Declaration\", \"fr\": \"Déclaration\"}, \"required\": true, \"normalize\": \"none\", \"boxPadding\": \"m\", \"clearLabel\": {\"en\": \"Clear\", \"fr\": \"Effacer\"}, \"labelClass\": \"govuk-label--m\", \"storageKey\": \"indigenous_declaration\", \"actionLabel\": {\"en\": \"Sign Now\", \"fr\": \"Signer maintenant\"}, \"placeholder\": {\"en\": \"First Last\", \"fr\": \"Prénom Nom\"}, \"handwritingFont\": \"cursive\", \"statusSignedText\": {\"en\": \"Signed\", \"fr\": \"Signé\"}, \"statusUnsignedText\": {\"en\": \"Not signed\", \"fr\": \"Non signé\"}}], \"nextStepId\": \"conflict-of-interest\", \"description\": {\"en\": \"\", \"fr\": \"\"}}, {\"type\": \"schema\", \"title\": {\"en\": \"Conflict of Interest\", \"fr\": \"Conflict of Interest\"}, \"stepId\": \"conflict-of-interest\", \"components\": [{\"id\": \"paragraph\", \"text\": {\"en\": \"Conflict of Interest and Bias Declaration\", \"fr\": \"Déclaration de conflit d’intérêts et de partialité\"}, \"type\": \"paragraph\", \"class\": \"govuk-heading-l\"}, {\"id\": \"paragraph-2\", \"text\": {\"en\": \"The Indigenous Skills and Employment Training (ISET) program is committed to fairness, transparency, and accountability in all funding decisions.\", \"fr\": \"Le programme de formation aux compétences et à l’emploi des Autochtones (PTCEA) s’engage à assurer l’équité, la transparence et la responsabilité dans toutes les décisions de financement.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-3\", \"text\": {\"en\": \"To protect the integrity of the program, all applicants must declare any actual, potential, or perceived conflicts of interest or biases related to their ISET application.\", \"fr\": \"Pour protéger l’intégrité du programme, tous les candidats doivent déclarer tout conflit d’intérêts ou biais réels, potentiels ou perçus liés à leur demande dans le cadre du PTCEA.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-4\", \"text\": {\"en\": \"1.      I do not have any personal, family, financial, or other relationship with any staff member of the Native Women’s Association of Canada (NWAC) or any regional Provincial/Territorial Member Association (PTMA) that could influence or appear to influence the assessment or approval of my ISET application.\", \"fr\": \"1.      Je n’ai aucune relation personnelle, familiale, financière ou autre avec un membre du personnel de l’Association des femmes autochtones du Canada (AFAC) ou de toute association régionale provinciale/territoriale (ARPT) qui pourrait influencer ou sembler influencer l’évaluation ou l’approbation de ma demande PTCEA.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-5\", \"text\": {\"en\": \"2.      I have not attempted to influence or put pressure on any NWAC or regional PTMA staff involved in assessing or approving my ISET application.\", \"fr\": \"2.      Je n’ai pas tenté d’influencer ou de faire pression sur un membre du personnel de l’AFAC ou de l’ARPT impliqué dans l’évaluation ou l’approbation de ma demande PTCEA.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-6\", \"text\": {\"en\": \"3.      I have not requested that my application be given priority ahead of other applicants, as I understand my application will be assessed in the order in which it was received by NWAC and/or the regional PTMA.\", \"fr\": \"3.      Je n’ai pas demandé que ma demande soit traitée en priorité par rapport à d’autres candidats, car je comprends que ma demande sera évaluée dans l’ordre où elle a été reçue par l’AFAC et/ou l’ARPT régional.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-7\", \"text\": {\"en\": \"4.      I have disclosed below any relationships, positive or negative biases, or circumstances that may create a real or perceived conflict of interest.\", \"fr\": \"4.      J’ai divulgué ci-dessous toute relation, biais positif ou négatif, ou circonstance pouvant créer un conflit d’intérêts réel ou perçu.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"conflict-of-interest\", \"hint\": {\"en\": \"Please select an option\", \"fr\": \"Veuillez sélectionner une option\"}, \"name\": \"conflict_of_interest\", \"type\": \"radio\", \"class\": \"govuk-radios\", \"label\": {\"en\": \"I confirm that\", \"fr\": \"Je confirme que\"}, \"options\": [{\"label\": {\"en\": \"I have no conflicts of interest or biases to declare \", \"fr\": \"Je n’ai aucun conflit d’intérêts ou biais à déclarer \"}, \"value\": \"no_conflict\"}, {\"label\": {\"en\": \"I wish to declare the following potential conflicts or biases\", \"fr\": \"Je souhaite déclarer les conflits ou biais potentiels suivants\"}, \"value\": \"conflict\", \"children\": [{\"id\": \"2022-conflict-follow\", \"type\": \"textarea\", \"class\": \"govuk-textarea\", \"label\": {\"en\": \"Please declare your potential conflict(s) and/or bias(es)\", \"fr\": \"Veuillez déclarer vos conflit(s) potentiel(s) et/ou biais\"}, \"required\": false, \"normalize\": \"trim\", \"labelClass\": \"govuk-label--m\", \"storageKey\": \"2022_conflict_follow\"}]}], \"required\": true, \"normalize\": \"none\", \"storageKey\": \"conflict_of_interest\", \"validation\": {\"required\": true, \"requiredMessage\": {\"en\": \"Please declare whether you have a conflict\", \"fr\": \"Déclarez, s’il vous plaît, si vous avez un conflit d’intérêts.\"}}, \"legendClass\": \"govuk-fieldset__legend--s\"}, {\"id\": \"conflict-applicant-signature\", \"hint\": {\"en\": \"Enter your full legal name then press Sign.\", \"fr\": \"Entrez votre nom légal complet puis appuyez sur Signer.\"}, \"type\": \"signature-ack\", \"label\": {\"en\": \"Type your full name to sign\", \"fr\": \"Tapez votre nom complet pour signer\"}, \"required\": true, \"normalize\": \"none\", \"boxPadding\": \"m\", \"clearLabel\": {\"en\": \"Clear\", \"fr\": \"Effacer\"}, \"labelClass\": \"govuk-label--m\", \"storageKey\": \"conflict_applicant_signature\", \"actionLabel\": {\"en\": \"Sign now\", \"fr\": \"Signer maintenant\"}, \"placeholder\": {\"en\": \"First Last\", \"fr\": \"Prénom Nom\"}, \"handwritingFont\": \"cursive\", \"statusSignedText\": {\"en\": \"Signed\", \"fr\": \"Signé\"}, \"statusUnsignedText\": {\"en\": \"Unsigned\", \"fr\": \"Non signé\"}}], \"nextStepId\": \"social-insurance-number\", \"description\": {\"en\": \"\", \"fr\": \"\"}}, {\"type\": \"schema\", \"title\": {\"en\": \"Social Insurance Number\", \"fr\": \"Social Insurance Number\"}, \"stepId\": \"social-insurance-number\", \"components\": [{\"id\": \"social-insurance-number\", \"hint\": {\"en\": \"We need your Social Insurance Number to process your request. It will only be used to confirm your eligibility and won’t be shared without your permission.  Your 9-digit Social Insurance Number (e.g., 123 456 789)\", \"fr\": \"Nous avons besoin de votre numéro d\'assurance sociale pour traiter votre demande. Il ne sera utilisé qu\'à des fins de confirmation de votre éligibilité et ne sera pas partagé sans votre autorisation. Votre numéro d\'assurance sociale de 9 chiffres (par exemple, 123 456 789)\"}, \"mask\": \"sin-ca\", \"type\": \"input\", \"class\": \"govuk-input\", \"label\": {\"en\": \"What is your Social Insurance Number (SIN)?\", \"fr\": \"Quel est votre numéro d\'assurance sociale (NAS) ?\"}, \"required\": true, \"inputMode\": \"numeric\", \"inputType\": \"text\", \"normalize\": \"trim\", \"labelClass\": \"govuk-label--m\", \"spellcheck\": false, \"storageKey\": \"social-insurance-number\", \"validation\": {\"rules\": [{\"id\": \"rule-1763511671307-0812\", \"type\": \"length\",