ion\": {\"en\": \"\", \"fr\": \"\"}}, {\"type\": \"schema\", \"title\": {\"en\": \"Disability and Social Assistance\", \"fr\": \"Disability and Social Assistance\"}, \"stepId\": \"disability-and-social-assistance\", \"components\": [{\"id\": \"paragraph\", \"text\": {\"en\": \"Disability and Social Assistance\", \"fr\": \"Handicap et Aide sociale\"}, \"type\": \"paragraph\", \"class\": \"govuk-heading-l\"}, {\"id\": \"paragraph-2\", \"text\": {\"en\": \"This section helps us understand any additional supports you may require.\", \"fr\": \"Cette section nous aide à comprendre quel ou quels soutiens supplémentaires vous pourriez nécessiter.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body-l\"}, {\"id\": \"has-disability\", \"name\": \"has-disability\", \"type\": \"radio\", \"class\": \"govuk-radios--inline\", \"label\": {\"en\": \"Do you consider yourself to have a disability?\", \"fr\": \"Est-ce que vous considérez avoir un handicap ?\"}, \"options\": [{\"label\": {\"en\": \"Yes\", \"fr\": \"Oui\"}, \"value\": \"yes\", \"children\": [{\"id\": \"disability-description\", \"hint\": {\"en\": \"Optional. Only required if you answered \'Yes\' to the previous question.\", \"fr\": \"Facultatif. Requis uniquement si vous avez répondu \'Oui\' à la question précédente.\"}, \"rows\": 5, \"type\": \"character-count\", \"label\": {\"en\": \"Please specify your disability\", \"fr\": \"Veuillez spécifier votre handicap\"}, \"required\": false, \"maxLength\": 200, \"normalize\": \"none\", \"threshold\": 75, \"labelClass\": \"govuk-label--s\", \"storageKey\": \"disability-description\"}]}, {\"label\": {\"en\": \"No\", \"fr\": \"Non\"}, \"value\": \"no\"}], \"required\": false, \"normalize\": \"yn-01\", \"storageKey\": \"has-disability\", \"legendClass\": \"govuk-fieldset__legend--m\"}, {\"id\": \"social-assistance\", \"hint\": {\"en\": \"You can only choose one\", \"fr\": \"Vous choisir une option seulement.\"}, \"name\": \"social-assistance\", \"type\": \"radio\", \"class\": \"g