umentTypes\": [\"equipment_quote\"]}, {\"id\": \"institution-letter\", \"label\": \"Institution letter\", \"notes\": \"If needed.\", \"sources\": [\"application_submission\", \"manual_upload\", \"secure_message_attachment\"], \"required\": false, \"documentTypes\": [\"institution_letter\"]}, {\"id\": \"receipt\", \"label\": \"Receipt\", \"notes\": \"If needed for the payment packet line-item category.\", \"sources\": [\"application_submission\", \"manual_upload\", \"secure_message_attachment\"], \"required\": false, \"documentTypes\": [\"receipt\"]}, {\"id\": \"wage-plan-mercs-schedule\", \"label\": \"Wage plan / MERCs schedule\", \"notes\": \"If needed for the payment packet line-item category.\", \"sources\": [\"application_submission\", \"manual_upload\", \"secure_message_attachment\"], \"required\": false, \"documentTypes\": [\"wage_plan\"]}], \"label\": \"Gate 8 - Send Payment Packet to Finance\", \"statuses\": [\"initiated\", \"active\", \"dormant\", \"ready_to_close\"], \"statusScope\": \"case\"}, {\"id\": \"trigger_recurring_payment\", \"items\": [{\"id\": \"attendance-form\", \"label\": \"Attendance form\", \"notes\": \"Monthly.\", \"sources\": [\"application_submission\", \"manual_upload\", \"secure_message_attachment\"], \"required\": true, \"documentTypes\": [\"attendance_form\"]}], \"label\": \"Gate 9 - Trigger a Recurring Payment\", \"statuses\": [\"initiated\", \"active\", \"dormant\", \"ready_to_close\"], \"statusScope\": \"case\"}, {\"id\": \"on_demand\", \"items\": [{\"id\": \"media-consent\", \"label\": \"Media consent\", \"notes\": \"Not tied to a specific gate; request if/when needed.\", \"sources\": [\"application_submission\", \"manual_upload\", \"secure_message_attachment\"], \"required\": false, \"documentTypes\": [\"media_consent\"]}], \"label\": \"On-demand (not tied to a specific gate)\", \"statuses\": [\"submitted\", \"in_review\", \"docs_requested\", \"closure_notice\", \"pending_approval\"], \"statusScope\": \"application\"}], \"label\