INSERT INTO `step_component` VALUES (704,91,1,29,'{\"id\": \"text-block\", \"html\": \"\", \"name\": \"text-block\", \"text\": {\"en\": \"Disability and Social Assistance\", \"fr\": \"Handicap et Aide sociale\"}, \"classes\": \"govuk-heading-l\"}','2025-09-03 11:38:39','2025-09-03 11:38:39'),(705,91,2,29,'{\"id\": \"text-block-2\", \"html\": \"\", \"name\": \"text-block-2\", \"text\": {\"en\": \"This section helps us understand any additional supports you may require.\", \"fr\": \"Cette section nous aide à comprendre quel ou quels soutiens supplémentaires vous pourriez nécessiter.\"}, \"classes\": \"govuk-body-l\"}','2025-09-03 11:38:39','2025-09-03 11:38:39'),(706,91,3,1,'{\"id\": \"example-radio\", \"hint\": {\"text\": {\"en\": \"\"}}, \"name\": \"has-disability\", \"items\": [{\"text\": {\"en\": \"Yes\", \"fr\": \"Oui\"}, \"value\": \"yes\", \"conditionalChildId\": \"disability-description\"}, {\"text\": {\"en\": \"No\", \"fr\": \"Non\"}, \"value\": \"no\"}], \"classes\": \"govuk-radios--inline\", \"disabled\": false, \"fieldset\": {\"legend\": {\"text\": {\"en\": \"Do you consider yourself to have a disability?\", \"fr\": \"Est-ce que vous considérez avoir un handicap ?\"}, \"classes\": \"govuk-fieldset__legend--m\", \"isPageHeading\": false}}, \"formGroup\": {\"classes\": \"\"}}','2025-09-03 11:38:39','2025-09-03 11:38:39'),(707,91,4,31,'{\"id\": \"example-character-count\", \"hint\": {\"text\": {\"en\": \"Optional. Only required if you answered \'Yes\' to the previous question.\", \"fr\": \"Facultatif. Requis uniquement si vous avez répondu \'Oui\' à la question précédente.\"}}, \"name\": \"disability-description\", \"rows\": 5, \"label\": {\"text\": {\"en\": \"Please specify your disability\", \"fr\": \"Veuillez spécifier votre handicap\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"classes\": \"\", \"maxwords\": \"\", \"formGroup\": {\"classes\": \"\"}, \"maxlength\": 200, \"threshold\": 75, \"spellcheck\": true, \"autocomplete\": \"\", \