"hint\": {\"text\": {\"en\": \"\"}}, \"name\": \"address-city\", \"type\": \"text\", \"label\": {\"text\": {\"en\": \"City\", \"fr\": \"Ville\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"\", \"spellcheck\": false, \"validation\": {\"rules\": [], \"required\": true}, \"autocomplete\": \"address-level2\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-12-15 13:46:38','2025-12-15 13:46:38'),(3194,83,5,2,'{\"id\": \"address-province\", \"hint\": {\"text\": {\"en\": \"Select which provice or territory you live in.\", \"fr\": \"Sélectionnez la province ou le territoire où vous résidez.\"}}, \"name\": \"address-province\", \"items\": [{\"text\": {\"en\": \"Alberta\", \"fr\": \"Alberta\"}, \"value\": \"ab\"}, {\"text\": {\"en\": \"British Columbia\", \"fr\": \"Colombie-Britannique\"}, \"value\": \"bc\"}, {\"text\": {\"en\": \"Manitoba\", \"fr\": \"Manitoba\"}, \"value\": \"mb\"}, {\"text\": {\"en\": \"New Brunswick\", \"fr\": \"Nouveau-Brunswick\"}, \"value\": \"nb\"}, {\"text\": {\"en\": \"Newfoundland and Labrador\", \"fr\": \"Terre-Neuve-et-Labrador\"}, \"value\": \"nl\"}, {\"text\": {\"en\": \"Northwest Territories\", \"fr\": \"Territoires du Nord-Ouest\"}, \"value\": \"nt\"}, {\"text\": {\"en\": \"Nova Scotia\", \"fr\": \"Nouvelle-Écosse\"}, \"value\": \"ns\"}, {\"text\": {\"en\": \"Nunavut\", \"fr\": \"Nunavut\"}, \"value\": \"nu\"}, {\"text\": {\"en\": \"Ontario\", \"fr\": \"Ontario\"}, \"value\": \"on\"}, {\"text\": {\"en\": \"Prince Edward Island\", \"fr\": \"Île-du-Prince-Édouard\"}, \"value\": \"pe\"}, {\"text\": {\"en\": \"Quebec\", \"fr\": \"Québec\"}, \"value\": \"qc\"}, {\"text\": {\"en\": \"Saskatchewan\", \"fr\": \"Saskatchewan\"}, \"value\": \"sk\"}, {\"text\": {\"en\": \"Yukon\", \"fr\": \"Yukon\"}, \"value\": \"yt\"}], \"label\": {\"text\": {\"en\": \"Province or Territory\", \"fr\": \"Province ou territoire\"}, \"classes\": \"govuk-label--s\"}, \"props\": {\"mode\": \"static\", \"endpoint\": null, \"attributes\": null}, \"validation\": {\"rules\": [], \"required\": true}}','2025-12-15 13:46:38','2025-12-15 13:46:38'),(3195,83,6,26,'{\"id\": \"example-input-3\", \"hint\": {\"text\": {\"en\": \"\"}}, \"mask\": \"postal-code-ca\", \"name\": \"address-postcode\", \"type\": \"text\", \"label\": {\"text\": {\"en\": \"Postal Code\", \"fr\": \"Code postal\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"\", \"spellcheck\": true, \"validation\": {\"rules\": [], \"required\": false}, \"autocomplete\": \"postal-code\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-12-15 13:46:38','2025-12-15 13:46:38'),(3196,83,7,26,'{\"id\": \"example-input-4\", \"hint\": {\"text\": {\"en\": \"Include area code (e.g., 613-555-1234).\", \"fr\": \"Incluez l\'indicatif régional (ex., 613-555-1234).\"}}, \"mask\": \"phone-na\", \"name\": \"telephone-day\", \"type\": \"tel\", \"label\": {\"text\": {\"en\": \"Daytime Phone Number\", \"fr\": \"Numéro de téléphone en journée\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"tel\", \"spellcheck\": false, \"autocomplete\": \"tel\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-12-15 13:46:38','2025-12-15 13:46:38'),(3197,83,8,26,'{\"id\": \"example-input-6\", \"hint\": {\"text\": {\"en\": \"We will use this to contact you about your application.\", \"fr\": \"Nous utiliserons cette adresse pour vous contacter au sujet de votre demande.\"}}, \"name\": \"contact-email-address\", \"type\": \"email\", \"label\": {\"text\": {\"en\": \"Email Address\", \"fr\": \"Adresse courriel\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"email\", \"spellcheck\": false, \"autocomplete\": \"email\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-12-15 13:46:38','2025-12-15 13:46:38'),(3198,83,9,26,'{\"id\": \"example-input-5\", \"hint\": {\"text\": {\"en\": \"Include area code.\", \"fr\": \"Incluez l\'indicatif régional.\"}}, \"mask\": \"phone-na\", \"name\": \"telephone-alt\", \"type\": \"tel\", \"label\": {\"text\": {\"en\": \"Alternative Phone Number (optional)\", \"fr\": \"Numéro de téléphone alternatif (facultatif)\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"tel\", \"spellcheck\": true, \"validation\": {\"rules\": [], \"required\": false}, \"autocomplete\": \"\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-12-15 13:46:38','2025-12-15 13:46:38'),(3199,83,10,32,'{\"id\": \"example-textarea\", \"hint\": {\"text\": {\"en\": \"Leave blank if your mailing address is the same as your street address.\", \"fr\": \"N\'incluez pas d\'informations personnelles ou financières.\"}}, \"name\": \"address-mailing-address\", \"rows\": 5, \"label\": {\"text\": {\"en\": \"Mailing Address (if different)\", \"fr\": \"Champ multi-lignes\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"classes\": \"govuk-textarea\", \"formGroup\": {\"classes\": \"\"}, \"spellcheck\": false, \"autocomplete\": \"mailing_address\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-12-15 13:46:38','2025-12-15 13:46:38'),(3200,140,1,29,'{\"id\": \"text-block\", \"html\": \"\", \"name\": \"text-block\", \"text\": {\"en\": \"I, the undersigned, acknowledge that I have been advised by the Native Women’s Association of Canada and/or its sub-agreement holders to the Indigenous Skills and Employment Training Program (hereinafter referred to as ISET) that funding for skills and employment training, living allowance, wage subsidies or other sources of funding are Government of Canada resources advanced through Employment and Social Development Canada (ESDC) to fund the ISET program.\", \"fr\": \"Je, soussigné(e), reconnais avoir été avisé(e) par l’Association des femmes autochtones du Canada et/ou ses détenteurs de sous-entente du Programme de formation et d’emploi pour les compétences autochtones (ci-après appelé ISET) que les fonds destinés à la formation en compétences et à l’emploi, à l’allocation de subsistance, aux subventions salariales ou à d’autres sources de financement sont des ressources du gouvernement du Canada avancées par l’entremise d’Emploi et Développement social Canada (EDSC) pour financer le programme ISET.\"}, \"classes\": \"govuk-body\"}','2025-12-17 09:23:48','2025-12-17 09:23:48'),(3201,140,2,29,'{\"id\": \"text-block-2\", \"html\": \"\", \"name\": \"text-block-2\", \"text\": {\"en\": \"I give my consent to the Native Women’s Association of Canada and/or its sub-agreement holders and their designated authorized representatives, to contact other service agencies, funding providers, educational and training institutions to verify information regarding my application and for verification of household income sources.\", \"fr\": \"J’autorise l’Association des femmes autochtones du Canada et/ou ses détenteurs de sous-entente et leurs représentants autorisés désignés à communiquer avec d’autres organismes de services, bailleurs de fonds, établissements d’enseignement et de formation afin de vérifier les renseignements concernant ma demande et pour la vérification des sources de revenu de mon ménage.\"}, \"classes\": \"govuk-body\"}','2025-12-17 09:23:48','2025-12-17 09:23:48'),(3202,140,3,29,'{\"id\": \"text-block-3\", \"html\": \"\", \"name\": \"text-block-3\", \"text\": {\"en\": \"Requests for supporting documentation may include but is not limited to: acceptance letter from training institution, letter of decision by Band; ID (Status/Treaty Card, driver’s license, Passport, Health Card or other Government-issued identification); tax assessments; child tax benefit (CTB) statement; Social Assistance statement or letter from agency/caseworker; Record of Employment (ROE); paystubs; letter of employment, bank statements, and other documentation as may be required for verification purposes.\", \"fr\": \"Les demandes de documents à l’appui peuvent inclure, sans toutefois s’y limiter : lettre d’acceptation de l’établissement de formation, lettre de décision du conseil de bande; pièce d’identité (carte de statut/de traité, permis de conduire, passeport, carte Santé ou autre pièce d’identité délivrée par un gouvernement); avis de cotisation; relevé de la prestation fiscale pour enfants (PFE); relevé d’aide sociale ou lettre de l’organisme/travailleur social; relevé d’emploi (RE); talons de paie; lettre d’emploi, relevés bancaires et tout autre document pouvant être exigé à des fins de vérification.\"}, \"classes\": \"govuk-body\"}','2025-12-17 09:23:48','2025-12-17 09:23:48'),(3203,140,4,29,'{\"id\": \"text-block-4\", \"html\": \"\", \"name\": \"text-block-4\", \"text\": {\"en\": \"I understand and acknowledge that any false or misleading statements and/or omission of information by me, may be grounds for immediate suspension of any funding and further, revocation of any funding arrangement between me and the Native Women’s Association of Canada and/or its sub-agreement holders, and may result in a repayment of funds to Employment and Social Development Canada (ESDC), for monies I received to which I was not entitled.\", \"fr\": \"Je comprends et reconnais que toute déclaration fausse ou trompeuse et/ou omission de renseignements de ma part peut constituer un motif de suspension immédiate de tout financement et, de plus, de révocation de toute entente de financement entre moi et l’Association des femmes autochtones du Canada et/ou ses détenteurs de sous-entente, et peut entraîner le remboursement à Emploi et Développement social Canada (EDSC) des sommes que j’ai reçues et auxquelles je n’avais pas droit.\"}, \"classes\": \"govuk-body\"}','2025-12-17 09:23:48','2025-12-17 09:23:48'),(3204,140,5,35,'{\"id\": \"legal_submission_sig\", \"hint\": {\"text\": {\"en\": \"Enter your full legal name then press Sign.\", \"fr\": \"Entrez votre nom légal complet, puis appuyez sur « Signer maintenant ».\"}}, \"name\": \"sig_caofs\", \"label\": {\"text\": {\"en\": \"Type your full name to sign\", \"fr\": \"Inscrivez votre nom complet pour signer\"}, \"classes\": \"govuk-label--m\"}, \"required\": true, \"formGroup\": {\"classes\": \"\"}, \"boxPadding\": \"m\", \"clearLabel\": {\"text\": {\"en\": \"Clear\", \"fr\": \"Effacer\"}}, \"actionLabel\": {\"text\": {\"en\": \"Sign Now\", \"fr\": \"Signer maintenant\"}}, \"placeholder\": {\"text\": {\"en\": \"First Last\", \"fr\": \"Prénom Nom\"}}, \"handwritingFont\": \"cursive\", \"statusSignedText\": {\"text\": {\"en\": \"Signed\", \"fr\": \"Signé\"}}, \"statusUnsignedText\": {\"text\": {\"en\": \"Not signed\", \"fr\": \"Non signé\"}}}','2025-12-17 09:23:48','2025-12-17 09:23:48'),(3233,135,1,29,'{\"id\": \"text-block\", \"html\": \"\", \"name\": \"text-block\", \"text\": {\"en\": \"EFT Direct Deposit Details\", \"fr\": \"Détails du dépôt direct par TEF\"}, \"classes\": \"govuk-heading-m\"}','2025-12-18 09:35:39','2025-12-18 09:35:39'),(3234,135,2,29,'{\"id\": \"text-block-2\", \"html\": \"\", \"name\": \"text-block-2\", \"text\": {\"en\": \"Provide the banking information for the Canadian account where you want your ISET funding deposited.\\nThese details must match what appears on your bank statement or void cheque.\", \"fr\": \"Fournissez les renseignements bancaires du compte canadien où vous souhaitez que votre financement ISET soit déposé.\\nCes renseignements doivent correspondre à ce qui figure sur votre relevé bancaire ou votre chèque annulé.\"}, \"classes\": \"govuk-body\"}','2025-12-18 09:35:39','2025-12-18 09:35:39'),(3235,135,3,26,'{\"id\": \"example-input\", \"hint\": {\"text\": {\"en\": \"The bank or credit union where your account is held (e.g., RBC, TD, CIBC, Desjardins).\", \"fr\": \"La banque ou la caisse populaire où est détenu votre compte (p. ex., RBC, TD, CIBC, Desjardins).\"}}, \"mask\": \"\", \"name\": \"eft-nameofbank\", \"type\": \"text\", \"label\": {\"text\": {\"en\": \"Name of Financial Institution\", \"fr\": \"Nom de l’institution financière\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"\", \"spellcheck\": false, \"validation\": {\"rules\": [], \"required\": true, \"requiredMessage\": {\"en\": \"Required\"}}, \"autocomplete\": \"\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-12-18 09:35:39','2025-12-18 09:35:39'),(3236,135,4,26,'{\"id\": \"example-input-2\", \"hint\": {\"text\": {\"en\": \"This is your branch number. You’ll find it on your void cheque or online banking.\", \"fr\": \"Il s’agit du numéro de votre succursale. Vous le trouverez sur votre chèque annulé ou dans vos services bancaires en ligne.\"}}, \"mask\": \"\", \"name\": \"eft-transit\", \"type\": \"text\", \"label\": {\"text\": {\"en\": \"Transit Number (5 digits)\", \"fr\": \"Numéro de transit (5 chiffres)\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"^[0-9]{5}$\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"numeric\", \"spellcheck\": true, \"validation\": {\"rules\": [], \"required\": true, \"requiredMessage\": {\"en\": \"Required\"}}, \"autocomplete\": \"\", \"errorMessage\": {\"te